declare(strict_types=1); require_once __DIR__ . '/includes/bootstrap.php'; require_once __DIR__ . '/config/app.php'; $number=trim((string)($_GET['order']??''));if(!$number||empty($_SESSION['tracked_orders'][$number])||$_SESSION['tracked_orders'][$number]<time()-1800){http_response_code(403);exit('Verify your order details on the tracking page before viewing a receipt.');}$statement=db()->prepare('SELECT * FROM orders WHERE order_number=?');$statement->bind_param('s',$number);$statement->execute();$order=$statement->get_result()->fetch_assoc();if(!$order){http_response_code(404);exit('Receipt not found.');}$statement=db()->prepare('SELECT * FROM order_items WHERE order_id=?');$statement->bind_param('i',$order['id']);$statement->execute();$items=$statement->get_result()->fetch_all(MYSQLI_ASSOC);require __DIR__ . '/includes/receipt_view.php'; exit;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><title>Receipt <?=e($order['order_number'])?></title><link rel="stylesheet" href="assets/css/style.css"></head><body><main class="receipt"><header><a class="brand" href="index.php"><span>ST</span> SAMMY TECH</a><p>0921628884 · sammytech1995@gmail.com<br>Juba, South Sudan</p></header><h1>Order receipt</h1><div class="receipt-meta"><p><b><?=e($order['order_number'])?></b><br><?=e(date('d M Y, H:i',strtotime($order['created_at'])))?></p><p><b><?=e($order['customer_name'])?></b><br><?=e($order['phone'])?></p></div><table><thead><tr><th>Item</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?=e($item['product_name'])?></td><td><?=e((string)$item['quantity'])?></td><td><?=money((float)$item['unit_price'])?></td><td><?=money((float)$item['unit_price']*$item['quantity'])?></td></tr><?php endforeach;?></tbody></table><p>Subtotal <b><?=money((float)$order['subtotal'])?></b></p><p>Delivery <b><?=money((float)$order['delivery_charge'])?></b></p><h2>Total <b><?=money((float)$order['total_amount'])?></b></h2><p>Payment: <?=e(ucwords(str_replace('_',' ',$order['payment_method'])))?> (<?=e($order['payment_status'])?>) · Order: <?=e($order['status'])?></p><button onclick="window.print()">Print receipt</button></main></body></html>
